// HLSL Simple PBR Normal & Lambertian Light Fragment Shader
float4 PSMain(VS_OUTPUT input) : SV_TARGET {
    float3 lightDir = normalize(LightPosition - input.WorldPos);
    float diff = max(dot(input.Normal, lightDir), 0.0);
    return float4(BaseColor.rgb * diff, 1.0);
}

// Simple State Machine Transition
enum class EnemyState { Patrol, Chase, Attack };
void UpdateEnemy(EnemyState& state, float distanceToPlayer) {
    if (distanceToPlayer < 2.0f) state = EnemyState::Attack;
    else if (distanceToPlayer < 10.0f) state = EnemyState::Chase;
    else state = EnemyState::Patrol;
}

